import{_ as t,o as n,c as r,ap as i}from"./chunks/framework.CuFS6FqL.js";const p=JSON.parse('{"title":"Datensicherheit","description":"Wie wir Kundendaten behandeln und während Pentests Evidenzen, Notizen und Berichte schützen.","frontmatter":{"title":"Datensicherheit","description":"Wie wir Kundendaten behandeln und während Pentests Evidenzen, Notizen und Berichte schützen."},"headers":[],"relativePath":"de/datensicherheit.md","filePath":"de/datensicherheit.md"}'),s={name:"de/datensicherheit.md"};function a(d,e,o,h,c,l){return n(),r("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /de/datensicherheit.md for this page in Markdown format</div><h1 id="datensicherheit" tabindex="-1">Datensicherheit <a class="header-anchor" href="#datensicherheit" aria-label="Permalink to &quot;Datensicherheit&quot;">​</a></h1><p>Wir verwalten unsere Notizen und Berichte in der von uns selbst entwickelten Pentest-Reporting-Lösung SysReptor (welche wir international an Pentesting-Teams vertreiben; source-available auf <a href="https://github.com/syslifters/sysreptor/" target="_blank" rel="noreferrer">GitHub</a>). Die Berechtigungsvergabe auf Projekte erfolgt stets nach dem Need-to-know-Prinzip. Gespeicherte Daten wie Bilder, Evidenzen, Datenbank-Einträge – sind serverseitig verschlüsselt (Encrypted Data at Rest; siehe auch <a href="https://docs.sysreptor.com/setup/configuration/#data-encryption-at-rest" target="_blank" rel="noreferrer">Dokumentation von SysReptor</a>) und die Übermittlung (Data in Transit) erfolgt ebenso verschlüsselt (mittels TLS/HTTPS).</p><p>Drei Monate nachdem ein (Re-)Test abgeschlossen wurde, werden die Berichte, Notizen und Evidenzen verschlüsselt und können nur mittels Hardware-Tokens und eines Vier-Augen-Prinzips wiederhergestellt werden (Verschlüsselung mittels Shamir-Secret-Sharing-Algorithmus; weitere Informationen: <a href="https://docs.sysreptor.com/insights/archiving/" target="_blank" rel="noreferrer">https://docs.sysreptor.com/insights/archiving/</a>), bis sie nach Ablauf unserer Aufbewahrungsfristen automatisch gelöscht werden.</p><p>Die Kommunikation zwischen Komponenten unserer internen Netzwerke erfolgt Ende-zu-Ende-verschlüsselt (mithilfe eines Tailscale-VPNs; teils mit mehreren Verschlüsselungs-Layern).</p><p>Wir stellen jedem Pentester ein Smartphone mit eigener Dienstnummer und einen Computer zur Verfügung. Die Privatnutzung ist aus Sicherheits- und Datenschutzgründen untersagt. Mitglieder von Projektteams kommunizieren mit dem Signal-Messenger und verschwindenden Nachrichten. Computer schützen wir mit IKARUS / HarfangLab (Endpunktschutz, Erkennung und Vulnerability Management).</p><p>Alle Web-Pentest-Aktivitäten werden über lokale Proxyserver der Pentester (<a href="https://portswigger.net/burp" target="_blank" rel="noreferrer">PortSwigger Burp</a>) protokolliert und drei Monate nach Abschluss der Pentests bzw. der Retests gelöscht.</p><p>Zudem verfügen wir über Vertraulichkeitsvereinbarungen mit unseren Mitarbeitern.</p>',8)])])}const g=t(s,[["render",a]]);export{p as __pageData,g as default};
